import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  reactStrictMode: true,
};

export default nextConfig;

const config = {
  plugins: {
    "@tailwindcss/postcss": {},
  },
};

export default config;

import { defineConfig, globalIgnores } from "eslint/config";
import nextVitals from "eslint-config-next/core-web-vitals";
import nextTypescript from "eslint-config-next/typescript";

export default defineConfig([
  ...nextVitals,
  ...nextTypescript,
  globalIgnores([".next/**", "node_modules/**"]),
]);

import { z } from "zod";

const nullableNumber = z.number().nullable().optional();
const nullableString = z.string().nullable().optional();

export const activitySchema = z.object({
  id: z.string(),
  name: z.string().optional().default("Course à pied"),
  type: z.string().optional().default("Run"),
  start_date_local: z.string().optional(),
  start_date: z.string().optional(),
  distance: nullableNumber,
  moving_time: nullableNumber,
  elapsed_time: nullableNumber,
  average_speed: nullableNumber,
  average_heartrate: nullableNumber,
  average_cadence: nullableNumber,
  total_elevation_gain: nullableNumber,
  temperature: nullableNumber,
  icu_training_load: nullableNumber,
});

export const activitiesSchema = z.array(activitySchema);

export const lapSchema = z.object({
  id: z.union([z.string(), z.number()]).optional(),
  name: nullableString,
  distance: nullableNumber,
  elapsed_time: nullableNumber,
  moving_time: nullableNumber,
  average_speed: nullableNumber,
  average_heartrate: nullableNumber,
  average_cadence: nullableNumber,
  recovery_time: nullableNumber,
});

export const lapsSchema = z.array(lapSchema);

export type Activity = z.infer<typeof activitySchema>;
export type Lap = z.infer<typeof lapSchema>;

import "server-only";

import { activitiesSchema, activitySchema, lapsSchema } from "./schemas";
import type { Activity, Lap } from "./schemas";

const API_URL = "https://intervals.icu/api/v1";

function credentials(): string {
  const apiKey = process.env.INTERVALS_API_KEY;
  const athleteId = process.env.INTERVALS_ATHLETE_ID;
  if (!apiKey || !athleteId) {
    throw new Error("Configuration Intervals.icu incomplète");
  }
  return Buffer.from(`API_KEY:${apiKey}`).toString("base64");
}

async function intervalsFetch(path: string): Promise<unknown> {
  const response = await fetch(`${API_URL}${path}`, {
    headers: { Authorization: `Basic ${credentials()}` },
    next: { revalidate: 60 },
  });
  if (response.status === 429) throw new Error("RATE_LIMIT");
  if (!response.ok) throw new Error(`INTERVALS_${response.status}`);
  return response.json() as Promise<unknown>;
}

export async function listRecentActivities(): Promise<Activity[]> {
  const athleteId = process.env.INTERVALS_ATHLETE_ID;
  if (!athleteId) throw new Error("Configuration Intervals.icu incomplète");
  const newest = new Date().toISOString().slice(0, 10);
  const oldest = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const payload = await intervalsFetch(`/athlete/${athleteId}/activities?oldest=${oldest}&newest=${newest}`);
  return activitiesSchema.parse(payload).filter((activity) => activity.type.toLowerCase() === "run");
}

export async function getActivity(id: string): Promise<{ activity: Activity; laps: Lap[] }> {
  const [activityPayload, lapsPayload] = await Promise.all([
    intervalsFetch(`/activity/${encodeURIComponent(id)}`),
    intervalsFetch(`/activity/${encodeURIComponent(id)}/laps`),
  ]);
  return { activity: activitySchema.parse(activityPayload), laps: lapsSchema.parse(lapsPayload) };
}

export function formatDistance(meters?: number | null): string {
  return meters == null ? "—" : `${(meters / 1000).toFixed(2).replace(".", ",")} km`;
}

export function formatDuration(seconds?: number | null): string {
  if (seconds == null) return "—";
  const minutes = Math.floor(seconds / 60);
  return `${minutes} min ${Math.round(seconds % 60).toString().padStart(2, "0")} s`;
}

export function formatPace(speed?: number | null): string {
  if (!speed || speed <= 0) return "—";
  const totalSeconds = Math.round(1000 / speed);
  return `${Math.floor(totalSeconds / 60)}'${String(totalSeconds % 60).padStart(2, "0")}/km`;
}

export function formatDate(value?: string): string {
  if (!value) return "Date inconnue";
  return new Intl.DateTimeFormat("fr-FR", { dateStyle: "medium" }).format(new Date(value));
}

import type { Metadata } from "next";
import "./globals.css";

export const metadata: Metadata = {
  title: "Run Insights",
  description: "Vos activités de course, simplement.",
};

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return <html lang="fr"><body>{children}</body></html>;
}

import { ActivityList } from "@/components/activity-list";

export default function HomePage() {
  return <main className="shell">
