}

import { ActivityDetail } from "@/components/activity-detail";

export default async function ActivityPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  return <ActivityDetail id={id} />;
}

import { NextResponse } from "next/server";
import { listRecentActivities } from "@/lib/intervals/client";

export async function GET() {
  try { return NextResponse.json(await listRecentActivities()); }
  catch (error) {
    const message = error instanceof Error ? error.message : "UNKNOWN";
    const status = message === "RATE_LIMIT" ? 429 : message.startsWith("INTERVALS_4") ? 502 : 500;
    return NextResponse.json({ error: message }, { status });
  }
}

import { NextResponse } from "next/server";
import { getActivity } from "@/lib/intervals/client";

export async function GET(_request: Request, { params }: { params: Promise<{ id: string }> }) {
  try { const { id } = await params; return NextResponse.json(await getActivity(id)); }
  catch (error) {
    const message = error instanceof Error ? error.message : "UNKNOWN";
    const status = message === "RATE_LIMIT" ? 429 : message.startsWith("INTERVALS_4") ? 502 : 500;
    return NextResponse.json({ error: message }, { status });
  }
}

"use client";

import { useEffect, useState } from "react";
import { ArrowUpRight, RefreshCw } from "lucide-react";
import type { Activity } from "@/lib/intervals/schemas";
import { formatDate, formatDistance, formatDuration, formatPace } from "@/lib/formatters";

type LoadState = "loading" | "ready" | "error";

export function ActivityList() {
  const [activities, setActivities] = useState<Activity[]>([]);
  const [state, setState] = useState<LoadState>("loading");
  const [error, setError] = useState<string>();
  async function loadActivities() {
    setState("loading");
    try {
      const response = await fetch("/api/activities");
      const payload: unknown = await response.json();
      if (!response.ok || !Array.isArray(payload)) throw new Error(response.status === 429 ? "RATE_LIMIT" : "FETCH_ERROR");
      setActivities(payload as Activity[]); setState("ready");
    } catch (loadError) { setError(loadError instanceof Error ? loadError.message : "FETCH_ERROR"); setState("error"); }
  }
  useEffect(() => { void loadActivities(); }, []);
  if (state === "loading") return <section className="panel state"><span className="spinner" />Chargement de vos activités...</section>;
  if (state === "error") return <section className="panel state error"><strong>Impossible de charger les activités.</strong><p>{error === "RATE_LIMIT" ? "La limite de requêtes Intervals.icu est atteinte. Réessayez dans quelques instants." : "Vérifiez vos variables .env.local et la connexion à Intervals.icu."}</p><button className="button" onClick={() => void loadActivities()}><RefreshCw size={16} /> Réessayer</button></section>;
  if (activities.length === 0) return <section className="panel state"><strong>Aucune course récente.</strong><p>Intervals.icu ne renvoie aucune activité de course sur les 90 derniers jours.</p></section>;
  return <section className="activities-section"><div className="section-heading"><div><p className="kicker">Synchronisées récemment</p><h2>Vos activités</h2></div><button className="icon-button" aria-label="Actualiser les activités" title="Actualiser" onClick={() => void loadActivities()}><RefreshCw size={18} /></button></div><div className="activity-grid">{activities.map((activity) => <a className="activity-card" href={`/activities/${encodeURIComponent(activity.id)}`} key={activity.id}><div className="card-top"><span>{formatDate(activity.start_date_local ?? activity.start_date)}</span><ArrowUpRight size={18} /></div><h3>{activity.name}</h3><span className="sport">{activity.type}</span><div className="metrics"><div><small>DISTANCE</small><strong>{formatDistance(activity.distance)}</strong></div><div><small>DURÉE</small><strong>{formatDuration(activity.moving_time ?? activity.elapsed_time)}</strong></div><div><small>ALLURE</small><strong>{formatPace(activity.average_speed)}</strong></div></div></a>)}</div></section>;
}

"use client";

import { useEffect, useState } from "react";
import { ArrowLeft, Timer } from "lucide-react";
import type { Activity, Lap } from "@/lib/intervals/schemas";
import { formatDate, formatDistance, formatDuration, formatPace } from "@/lib/formatters";

type Detail = { activity: Activity; laps: Lap[] };

export function ActivityDetail({ id }: { id: string }) {
  const [detail, setDetail] = useState<Detail>();
  const [error, setError] = useState<string>();
  useEffect(() => {
    fetch(`/api/activities/${encodeURIComponent(id)}`)
      .then(async (response) => { const payload: unknown = await response.json(); if (!response.ok) throw new Error(response.status === 429 ? "RATE_LIMIT" : "FETCH_ERROR"); return payload as Detail; })
      .then(setDetail)
      .catch((loadError: unknown) => setError(loadError instanceof Error ? loadError.message : "FETCH_ERROR"));
  }, [id]);

  if (error) return <main className="shell"><a className="back-link" href="/"><ArrowLeft size={16} /> Toutes les activités</a><section className="panel state error"><strong>Cette activité ne peut pas être chargée.</strong><p>{error === "RATE_LIMIT" ? "La limite de requêtes est atteinte. Réessayez plus tard." : "Vérifiez la configuration Intervals.icu ou l’identifiant de l’activité."}</p></section></main>;
  if (!detail) return <main className="shell"><a className="back-link" href="/"><ArrowLeft size={16} /> Toutes les activités</a><section className="panel state"><span className="spinner" />Chargement de la séance...</section></main>;

  const { activity, laps } = detail;
  return <main className="shell"><a className="back-link" href="/"><ArrowLeft size={16} /> Toutes les activités</a><section className="detail-head"><div><p className="kicker">{formatDate(activity.start_date_local ?? activity.start_date)} · {activity.type}</p><h1>{activity.name}</h1></div><span className="detail-mark"><Timer size={19} /> Données brutes</span></section><div className="summary-grid"><Summary label="Distance" value={formatDistance(activity.distance)} /><Summary label="Durée" value={formatDuration(activity.moving_time ?? activity.elapsed_time)} /><Summary label="Allure moyenne" value={formatPace(activity.average_speed)} /><Summary label="FC moyenne" value={activity.average_heartrate ? `${Math.round(activity.average_heartrate)} bpm` : "—"} /></div><section className="panel laps-panel"><div className="section-heading"><div><p className="kicker">Découpage de la séance</p><h2>Laps & intervalles</h2></div><span className="count">{laps.length} {laps.length > 1 ? "laps" : "lap"}</span></div>{laps.length === 0 ? <div className="empty-row">Aucun lap disponible pour cette activité.</div> : <div className="table-wrap"><table><thead><tr><th>Lap</th><th>Distance</th><th>Durée</th><th>Allure</th><th>FC moy.</th><th>Cadence</th></tr></thead><tbody>{laps.map((lap, index) => <tr key={String(lap.id ?? index)}><th>{lap.name ?? `Lap ${index + 1}`}</th><td>{formatDistance(lap.distance)}</td><td>{formatDuration(lap.moving_time ?? lap.elapsed_time)}</td><td>{formatPace(lap.average_speed)}</td><td>{lap.average_heartrate ? `${Math.round(lap.average_heartrate)} bpm` : "—"}</td><td>{lap.average_cadence ? `${Math.round(lap.average_cadence)} pas/min` : "—"}</td></tr>)}</tbody></table></div>}</section></main>;
}

function Summary({ label, value }: { label: string; value: string }) { return <div className="summary-item"><small>{label}</small><strong>{value}</strong></div>; }

