import { schema } from "./schema";

const databaseUrl = process.env.DATABASE_URL ?? "file:./data/run-insights.db";
const databasePath = databaseUrl.startsWith("file:") ? databaseUrl.slice("file:".length) : databaseUrl;

const globalForDatabase = globalThis as typeof globalThis & { runInsightsDatabase?: Database.Database };
const sqlite = globalForDatabase.runInsightsDatabase ?? new Database(databasePath);
sqlite.pragma("journal_mode = WAL");
if (process.env.NODE_ENV !== "production") globalForDatabase.runInsightsDatabase = sqlite;

export const db = drizzle(sqlite, { schema });
export type AppDatabase = typeof db;

import type { InferInsertModel, InferSelectModel } from "drizzle-orm";
import type { activityDetailsCache, activityStreamSummaries, athleteContextVersions, goals, manualSessions, syncedActivities, userConfirmations } from "./schema";

export type SyncedActivity = InferSelectModel<typeof syncedActivities>;
export type NewSyncedActivity = InferInsertModel<typeof syncedActivities>;
export type ManualSession = InferSelectModel<typeof manualSessions>;
export type NewManualSession = InferInsertModel<typeof manualSessions>;
export type Confirmation = InferSelectModel<typeof userConfirmations>;
export type NewConfirmation = InferInsertModel<typeof userConfirmations>;
export type AthleteContextVersion = InferSelectModel<typeof athleteContextVersions>;
export type NewAthleteContextVersion = InferInsertModel<typeof athleteContextVersions>;
export type Goal = InferSelectModel<typeof goals>;
export type NewGoal = InferInsertModel<typeof goals>;
export type ActivityDetailsCache = InferSelectModel<typeof activityDetailsCache>;
export type ActivityStreamSummary = InferSelectModel<typeof activityStreamSummaries>;

import { z } from "zod";

export const manualDisciplineSchema = z.enum(["strength_training", "swimming", "mobility", "other"]);
export const confirmationTypeSchema = z.enum(["performance_test_candidate", "cadence_drill_candidate", "session_intent_missing", "data_quality_review"]);
export const confirmationStatusSchema = z.enum(["detected", "confirmed", "dismissed"]);
export const detectionConfidenceSchema = z.enum(["low", "medium", "high"]);
export const contextStatusSchema = z.enum(["draft", "active", "archived"]);
export const goalPrioritySchema = z.enum(["primary", "secondary"]);
export const goalStatusSchema = z.enum(["active", "paused", "completed", "archived"]);
export const localDateSchema = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "La date doit respecter YYYY-MM-DD").refine((value) => !Number.isNaN(Date.parse(`${value}T00:00:00Z`)), "La date est invalide");

export const confirmationPayloadSchema = z.record(z.string(), z.unknown());
export const activityDetailCacheSchema = z.object({ id: z.string(), name: z.string().optional(), sportType: z.string().optional() }).strict();
export const streamSummarySchema = z.object({ version: z.string(), metrics: z.record(z.string(), z.number().finite()) }).strict();
export const athleteContextSchema = z.object({ goals: z.array(z.string()).default([]), weekTemplate: z.array(z.object({ dayOfWeek: z.number().int().min(0).max(6), label: z.string() }).strict()).default([]), notes: z.string().optional() }).strict();
export const goalDefinitionSchema = z.record(z.string(), z.unknown());

export type ManualDiscipline = z.infer<typeof manualDisciplineSchema>;
export type ConfirmationType = z.infer<typeof confirmationTypeSchema>;
export type ConfirmationStatus = z.infer<typeof confirmationStatusSchema>;
export type DetectionConfidence = z.infer<typeof detectionConfidenceSchema>;
export type ContextStatus = z.infer<typeof contextStatusSchema>;
export type GoalPriority = z.infer<typeof goalPrioritySchema>;
export type GoalStatus = z.infer<typeof goalStatusSchema>;
export type ConfirmationPayload = z.infer<typeof confirmationPayloadSchema>;
export type ActivityDetailCache = z.infer<typeof activityDetailCacheSchema>;
export type StreamSummary = z.infer<typeof streamSummarySchema>;
export type AthleteContext = z.infer<typeof athleteContextSchema>;
export type GoalDefinition = z.infer<typeof goalDefinitionSchema>;

export function serializeJson<T>(schema: z.ZodType<T>, value: T): string {
  return JSON.stringify(schema.parse(value));
}

export function parseJson<T>(schema: z.ZodType<T>, value: string): T {
  return schema.parse(JSON.parse(value) as unknown);
}

import { and, eq, gte, lte } from "drizzle-orm";
import { db as defaultDb, type AppDatabase } from "../client";
import { syncedActivities } from "../schema";
import type { NewSyncedActivity, SyncedActivity } from "../types";

export function createSyncedActivityRepository(database: AppDatabase = defaultDb) {
  return {
    async upsert(input: NewSyncedActivity): Promise<SyncedActivity> {
      const [row] = await database.insert(syncedActivities).values(input).onConflictDoUpdate({ target: syncedActivities.intervalsActivityId, set: { ...input, updatedAt: input.updatedAt } }).returning();
      return row;
    },
    async findById(id: string): Promise<SyncedActivity | undefined> { return database.query.syncedActivities.findFirst({ where: eq(syncedActivities.id, id) }); },
    async findByPeriod(from: string, to: string): Promise<SyncedActivity[]> { return database.select().from(syncedActivities).where(and(gte(syncedActivities.startDate, from), lte(syncedActivities.startDate, to))).orderBy(syncedActivities.startDate); },
    async update(id: string, changes: Partial<NewSyncedActivity>): Promise<SyncedActivity | undefined> { const [row] = await database.update(syncedActivities).set(changes).where(eq(syncedActivities.id, id)).returning(); return row; },
  };
}

import { and, eq, gte, lte } from "drizzle-orm";
import { db as defaultDb, type AppDatabase } from "../client";
import { manualSessions } from "../schema";
import { localDateSchema, manualDisciplineSchema } from "../contracts";
import type { ManualSession, NewManualSession } from "../types";

function validate(input: NewManualSession): NewManualSession {
  localDateSchema.parse(input.sessionDate);
  manualDisciplineSchema.parse(input.discipline);
  if (!Number.isInteger(input.durationMinutes) || input.durationMinutes <= 0) throw new Error("La durée doit être un entier strictement positif");
  return input;
}

export function createManualSessionRepository(database: AppDatabase = defaultDb) {
  return {
    async create(input: NewManualSession): Promise<ManualSession> { const [row] = await database.insert(manualSessions).values(validate(input)).returning(); return row; },
    async findById(id: string): Promise<ManualSession | undefined> { return database.query.manualSessions.findFirst({ where: eq(manualSessions.id, id) }); },
    async findByPeriod(from: string, to: string): Promise<ManualSession[]> { localDateSchema.parse(from); localDateSchema.parse(to); return database.select().from(manualSessions).where(and(gte(manualSessions.sessionDate, from), lte(manualSessions.sessionDate, to))).orderBy(manualSessions.sessionDate); },
    async update(id: string, changes: Partial<NewManualSession>): Promise<ManualSession | undefined> { if (changes.sessionDate) localDateSchema.parse(changes.sessionDate); if (changes.discipline) manualDisciplineSchema.parse(changes.discipline); if (changes.durationMinutes !== undefined && (!Number.isInteger(changes.durationMinutes) || changes.durationMinutes <= 0)) throw new Error("La durée doit être un entier strictement positif"); const [row] = await database.update(manualSessions).set(changes).where(eq(manualSessions.id, id)).returning(); return row; },
    async remove(id: string): Promise<void> { await database.delete(manualSessions).where(eq(manualSessions.id, id)); },
  };
}

import { eq } from "drizzle-orm";
import { db as defaultDb, type AppDatabase } from "../client";
import { confirmationPayloadSchema, confirmationStatusSchema, confirmationTypeSchema, detectionConfidenceSchema, parseJson, serializeJson } from "../contracts";
import { userConfirmations } from "../schema";
import type { Confirmation, NewConfirmation } from "../types";

export function createConfirmationRepository(database: AppDatabase = defaultDb) {
  return {
    async create(input: NewConfirmation): Promise<Confirmation> { confirmationTypeSchema.parse(input.confirmationType); confirmationStatusSchema.parse(input.status); detectionConfidenceSchema.parse(input.detectionConfidence); const proposed = parseJson(confirmationPayloadSchema, input.proposedPayloadJson); const [row] = await database.insert(userConfirmations).values({ ...input, proposedPayloadJson: serializeJson(confirmationPayloadSchema, proposed) }).returning(); return row; },
    async findById(id: string): Promise<Confirmation | undefined> { return database.query.userConfirmations.findFirst({ where: eq(userConfirmations.id, id) }); },
    async resolve(id: string, status: "confirmed" | "dismissed", payload?: Record<string, unknown>): Promise<Confirmation | undefined> { const now = new Date().toISOString(); const [row] = await database.update(userConfirmations).set({ status, resolvedAt: now, resolvedPayloadJson: payload ? serializeJson(confirmationPayloadSchema, payload) : null, updatedAt: now }).where(eq(userConfirmations.id, id)).returning(); return row; },
  };
}

import { and, eq, ne } from "drizzle-orm";
import { db as defaultDb, type AppDatabase } from "../client";
import { athleteContextSchema, contextStatusSchema, parseJson, serializeJson } from "../contracts";
import { athleteContextVersions } from "../schema";
import type { AthleteContextVersion, NewAthleteContextVersion } from "../types";

export function createAthleteContextRepository(database: AppDatabase = defaultDb) {
  return {
    async create(input: NewAthleteContextVersion): Promise<AthleteContextVersion> { contextStatusSchema.parse(input.status); const context = parseJson(athleteContextSchema, input.contextJson); const [row] = await database.insert(athleteContextVersions).values({ ...input, contextJson: serializeJson(athleteContextSchema, context) }).returning(); return row; },
    async findById(id: string): Promise<AthleteContextVersion | undefined> { return database.query.athleteContextVersions.findFirst({ where: eq(athleteContextVersions.id, id) }); },
    async findActive(): Promise<AthleteContextVersion | undefined> { return database.query.athleteContextVersions.findFirst({ where: eq(athleteContextVersions.status, "active") }); },
    async activate(id: string): Promise<AthleteContextVersion | undefined> { const now = new Date().toISOString(); return database.transaction((transaction) => { transaction.update(athleteContextVersions).set({ status: "archived", archivedAt: now, updatedAt: now }).where(and(eq(athleteContextVersions.status, "active"), ne(athleteContextVersions.id, id))).run(); const [row] = transaction.update(athleteContextVersions).set({ status: "active", activatedAt: now, updatedAt: now }).where(eq(athleteContextVersions.id, id)).returning().all(); return row; }); },
  };
}

import { and, eq, ne } from "drizzle-orm";
import { db as defaultDb, type AppDatabase } from "../client";
import { goalDefinitionSchema, goalPrioritySchema, goalStatusSchema, parseJson, serializeJson } from "../contracts";
import { goals } from "../schema";
import type { Goal, NewGoal } from "../types";

export function createGoalRepository(database: AppDatabase = defaultDb) {
  return {
    async create(input: NewGoal): Promise<Goal> { goalPrioritySchema.parse(input.priority); goalStatusSchema.parse(input.status); const definition = parseJson(goalDefinitionSchema, input.definitionJson); if (input.priority === "primary" && input.status === "active" && (await database.query.goals.findFirst({ where: and(eq(goals.priority, "primary"), eq(goals.status, "active")) }))) throw new Error("Un seul objectif principal actif est autorisé"); const [row] = await database.insert(goals).values({ ...input, definitionJson: serializeJson(goalDefinitionSchema, definition) }).returning(); return row; },
    async findById(id: string): Promise<Goal | undefined> { return database.query.goals.findFirst({ where: eq(goals.id, id) }); },
    async update(id: string, changes: Partial<NewGoal>): Promise<Goal | undefined> { if (changes.priority) goalPrioritySchema.parse(changes.priority); if (changes.status) goalStatusSchema.parse(changes.status); if (changes.definitionJson) { const definition = parseJson(goalDefinitionSchema, changes.definitionJson); changes.definitionJson = serializeJson(goalDefinitionSchema, definition); } if (changes.priority === "primary" && changes.status === "active" && (await database.query.goals.findFirst({ where: and(eq(goals.priority, "primary"), eq(goals.status, "active"), ne(goals.id, id)) }))) throw new Error("Un seul objectif principal actif est autorisé"); const [row] = await database.update(goals).set(changes).where(eq(goals.id, id)).returning(); return row; },
  };
}

import "server-only";

import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { schema } from "./schema";

const databaseUrl = process.env.DATABASE_URL ?? "file:./data/run-insights.db";
const databasePath = databaseUrl.startsWith("file:") ? databaseUrl.slice("file:".length) : databaseUrl;

const globalForDatabase = globalThis as typeof globalThis & { runInsightsDatabase?: Database.Database };

export function getDb() {
	const sqlite = globalForDatabase.runInsightsDatabase ?? new Database(databasePath);
	sqlite.pragma("journal_mode = WAL");
	if (process.env.NODE_ENV !== "production") globalForDatabase.runInsightsDatabase = sqlite;
	return drizzle(sqlite, { schema });
}

export type AppDatabase = ReturnType<typeof getDb>;

