import { randomUUID } from "node:crypto";
import { isSupportedRunningActivity } from "@/lib/activities/classification";
import type { AppDatabase } from "@/lib/db/client";
import { createSyncedActivityRepository } from "@/lib/db/repositories/synced-activity-repository";
import { fetchActivityList, parseActivityListItem } from "./client";
import { mapIntervalsActivityToSyncedActivityInsert } from "./mapper";

export type ActivitySyncPeriod = { weeks: number; oldest: string; newest: string };
export type ActivitySyncFailure = { activityId?: string; code: string; message: string };
export type ActivitySyncResult = { requestId: string; period: ActivitySyncPeriod; receivedCount: number; createdCount: number; updatedCount: number; unchangedCount: number; ignoredUnsupportedSportCount: number; invalidActivityCount: number; failedCount: number; failures: ActivitySyncFailure[]; syncedAt: string };

export function calculateSyncPeriod(weeks: number, now = new Date()): ActivitySyncPeriod {
  const newest = now.toISOString().slice(0, 10);
  const oldest = new Date(now.getTime() - weeks * 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  return { weeks, oldest, newest };
}

export async function synchronizeRunningActivities(options: { weeks: number; requestId?: string; database?: AppDatabase }): Promise<ActivitySyncResult> {
  const requestId = options.requestId ?? randomUUID();
  const syncedAt = new Date().toISOString();
  const period = calculateSyncPeriod(options.weeks);
  const repository = createSyncedActivityRepository(options.database);
  const payloads = await fetchActivityList({ requestId, oldest: period.oldest, newest: period.newest });
  const result: ActivitySyncResult = { requestId, period, receivedCount: payloads.length, createdCount: 0, updatedCount: 0, unchangedCount: 0, ignoredUnsupportedSportCount: 0, invalidActivityCount: 0, failedCount: 0, failures: [], syncedAt };
  for (const payload of payloads) {
    let activityId: string | undefined;
    try {
      const activity = parseActivityListItem(payload);
      activityId = activity.id;
      if (!isSupportedRunningActivity(activity)) { result.ignoredUnsupportedSportCount += 1; continue; }
      const outcome = await repository.upsertWithOutcome(mapIntervalsActivityToSyncedActivityInsert(activity, syncedAt));
      result[`${outcome.operation}Count`] += 1;
    } catch (error) {
      if (!activityId && typeof payload === "object" && payload !== null && "id" in payload && (typeof payload.id === "string" || typeof payload.id === "number")) activityId = String(payload.id);
      if (error instanceof Error && error.name === "ZodError") { result.invalidActivityCount += 1; result.failures.push({ activityId, code: "INVALID_ACTIVITY", message: "Activité ignorée : données invalides" }); }
      else { result.failedCount += 1; result.failures.push({ activityId, code: "DATABASE_ERROR", message: "Activité non synchronisée" }); }
    }
  }
  console.info("[sync] completed", { requestId, period, receivedCount: result.receivedCount, createdCount: result.createdCount, updatedCount: result.updatedCount, unchangedCount: result.unchangedCount, ignoredUnsupportedSportCount: result.ignoredUnsupportedSportCount, invalidActivityCount: result.invalidActivityCount, failedCount: result.failedCount });
  return result;
}

import "server-only";

import { activitiesListEnvelopeSchema, activitiesSchema, activityListItemSchema, activitySchema, intervalsSchema } from "./schemas";
import type { Activity, ActivityListItem, Lap } from "./schemas";

const API_URL = "https://intervals.icu/api/v1";

export type ActivityRequestContext = { requestId: string; activityId: string };

export class IntervalsApiError extends Error {
  constructor(public readonly status: number, message: string, public readonly endpoint: string, public readonly retryAfter?: string) {
    super(message);
    this.name = "IntervalsApiError";
  }
}

export class IntervalsValidationError extends Error {
  constructor(public readonly endpoint: string, public readonly receivedKeys: string[]) {
    super("Réponse Intervals.icu non conforme");
    this.name = "IntervalsValidationError";
  }
}

export type ActivityListRequest = { requestId: string; oldest: string; newest: string };

function credentials(): string {
  const apiKey = process.env.INTERVALS_API_KEY;
  const athleteId = process.env.INTERVALS_ATHLETE_ID;
  if (!apiKey || !athleteId) {
    throw new Error("Configuration Intervals.icu incomplète");
  }
  return Buffer.from(`API_KEY:${apiKey}`).toString("base64");
}

async function intervalsFetch(path: string, context: ActivityRequestContext): Promise<unknown> {
  const endpoint = `${API_URL}${path}`;
  console.info("[intervals] request", { requestId: context.requestId, activityId: context.activityId, endpoint: path });
  let response: Response;
  try {
    response = await fetch(endpoint, {
    headers: { Authorization: `Basic ${credentials()}` },
    next: { revalidate: 60 },
    });
  } catch {
    console.error("[intervals] network error", { requestId: context.requestId, activityId: context.activityId, endpoint: path });
    throw new IntervalsApiError(503, "Service Intervals.icu indisponible", path);
  }
  console.info("[intervals] response", { requestId: context.requestId, activityId: context.activityId, endpoint: path, status: response.status });
  if (!response.ok) throw new IntervalsApiError(response.status, "Erreur de réponse Intervals.icu", path, response.headers.get("retry-after") ?? undefined);
  let payload: unknown;
  try { payload = await response.json(); }
  catch { throw new IntervalsValidationError(path, ["invalid_json"]); }
  console.info("[intervals] payload keys", { requestId: context.requestId, activityId: context.activityId, endpoint: path, keys: Array.isArray(payload) ? ["array"] : typeof payload === "object" && payload !== null ? Object.keys(payload).slice(0, 20) : [typeof payload] });
  return payload;
}

export async function fetchActivityList(request: ActivityListRequest): Promise<unknown[]> {
  const athleteId = process.env.INTERVALS_ATHLETE_ID;
  if (!athleteId) throw new Error("Configuration Intervals.icu incomplète");
  const path = `/athlete/${athleteId}/activities?oldest=${request.oldest}&newest=${request.newest}`;
  const payload = await intervalsFetch(path, { requestId: request.requestId, activityId: "list" });
  try { return activitiesListEnvelopeSchema.parse(payload); }
  catch { throw new IntervalsValidationError(path, objectKeys(payload)); }
}

export function parseActivityListItem(payload: unknown): ActivityListItem {
  return activityListItemSchema.parse(payload);
}

export async function listRecentActivities(): Promise<Activity[]> {
  const athleteId = process.env.INTERVALS_ATHLETE_ID;
  if (!athleteId) throw new Error("Configuration Intervals.icu incomplète");
  const newest = new Date().toISOString().slice(0, 10);
  const oldest = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const payload = await intervalsFetch(`/athlete/${athleteId}/activities?oldest=${oldest}&newest=${newest}`, { requestId: "list", activityId: "list" });
  return activitiesSchema.parse(payload).filter((activity) => activity.type.toLowerCase() === "run");
}

export async function getActivity(id: string, requestId: string): Promise<{ activity: Activity; laps: Lap[] }> {
  const context = { requestId, activityId: id };
  const activityPath = `/activity/${encodeURIComponent(id)}`;
  const activityPayload = await intervalsFetch(activityPath, context);
  let activity: Activity;
  try { activity = activitySchema.parse(activityPayload); }
  catch { throw new IntervalsValidationError(activityPath, objectKeys(activityPayload)); }
  const lapsPath = `/activity/${encodeURIComponent(id)}/intervals`;
  try {
    const intervalsPayload = await intervalsFetch(lapsPath, context);
    try {
      const intervals = intervalsSchema.parse(intervalsPayload);
      return { activity, laps: intervals.icu_intervals.map((interval) => ({
        id: interval.id,
        name: interval.label ?? interval.type ?? null,
        distance: interval.distance,
        elapsed_time: interval.elapsed_time,
        moving_time: interval.moving_time,
        average_speed: interval.average_speed,
        average_heartrate: interval.average_heartrate,
        average_cadence: interval.average_cadence,
      })) };
    }
    catch { throw new IntervalsValidationError(lapsPath, objectKeys(intervalsPayload)); }
  } catch (error) {
    if (error instanceof IntervalsApiError && error.status === 404) return { activity, laps: [] };
    throw error;
  }
}

function objectKeys(payload: unknown): string[] {
  return typeof payload === "object" && payload !== null && !Array.isArray(payload) ? Object.keys(payload).slice(0, 20) : [Array.isArray(payload) ? "array" : typeof payload];
}

import { and, desc, eq, gte, lte } from "drizzle-orm";
import { getDb, type AppDatabase } from "../client";
import { syncedActivities } from "../schema";
import type { NewSyncedActivity, SyncedActivity } from "../types";

export type SyncedActivityUpsertOutcome = { activity: SyncedActivity; operation: "created" | "updated" | "unchanged" };

export function createSyncedActivityRepository(database: AppDatabase = getDb()) {
  return {
    async upsert(input: NewSyncedActivity): Promise<SyncedActivity> {
      const { id: _id, createdAt: _createdAt, ...changes } = input;
      const [row] = await database.insert(syncedActivities).values(input).onConflictDoUpdate({ target: syncedActivities.intervalsActivityId, set: { ...changes, updatedAt: input.updatedAt } }).returning();
      return row;
    },
    async upsertWithOutcome(input: NewSyncedActivity): Promise<SyncedActivityUpsertOutcome> {
      const existing = await database.query.syncedActivities.findFirst({ where: eq(syncedActivities.intervalsActivityId, input.intervalsActivityId) });
      if (existing && sameMappedFields(existing, input)) {
        const activity = await this.upsert(input);
        return { activity, operation: "unchanged" };
      }
      const activity = await this.upsert(input);
      return { activity, operation: existing ? "updated" : "created" };
    },
    async findByExternalId(intervalsActivityId: string): Promise<SyncedActivity | undefined> { return database.query.syncedActivities.findFirst({ where: eq(syncedActivities.intervalsActivityId, intervalsActivityId) }); },
    async findById(id: string): Promise<SyncedActivity | undefined> { return database.query.syncedActivities.findFirst({ where: eq(syncedActivities.id, id) }); },
    async findByPeriod(from: string, to: string, limit?: number): Promise<SyncedActivity[]> { const query = database.select().from(syncedActivities).where(and(gte(syncedActivities.startDate, from), lte(syncedActivities.startDate, to))).orderBy(desc(syncedActivities.startDate)); return limit === undefined ? query : query.limit(limit); },
    async update(id: string, changes: Partial<NewSyncedActivity>): Promise<SyncedActivity | undefined> { const [row] = await database.update(syncedActivities).set(changes).where(eq(syncedActivities.id, id)).returning(); return row; },
  };
}

function sameMappedFields(existing: SyncedActivity, input: NewSyncedActivity): boolean {
  const fields = ["intervalsActivityId", "startDate", "timezone", "name", "sportType", "distanceM", "movingTimeS", "elapsedTimeS", "elevationGainM", "averageSpeedMps", "averageHeartRateBpm", "maxHeartRateBpm", "averageCadenceSpm", "averagePowerW", "trainingLoad", "sourceUpdatedAt"] as const;
  return fields.every((field) => existing[field] === input[field]);
}

import { randomUUID } from "node:crypto";
import { NextResponse } from "next/server";
import { z } from "zod";
import { IntervalsApiError, IntervalsValidationError } from "@/lib/intervals/client";
import { synchronizeRunningActivities } from "@/lib/intervals/sync";

const bodySchema = z.object({ weeks: z.number().int().min(1).max(52).default(12) }).strict();

export async function POST(request: Request) {
  const requestId = randomUUID();
  try {
    const rawBody: unknown = await request.json().catch(() => ({}));
    const body = bodySchema.parse(rawBody);
    return NextResponse.json(await synchronizeRunningActivities({ weeks: body.weeks, requestId }));
  } catch (error) {
    if (error instanceof z.ZodError) return errorResponse("INVALID_WEEKS", "La période doit être un entier compris entre 1 et 52 semaines", requestId, 400);
    if (error instanceof IntervalsValidationError) return errorResponse("INTERVALS_VALIDATION_ERROR", "La réponse globale d’Intervals.icu est invalide", requestId, 502);
    if (error instanceof IntervalsApiError) return errorResponse(error.status === 429 ? "INTERVALS_RATE_LIMITED" : "INTERVALS_API_ERROR", error.status === 429 ? "Intervals.icu limite temporairement les requêtes" : "Intervals.icu est indisponible", requestId, error.status === 429 ? 429 : 502);
    console.error("[sync] unexpected error", { requestId, message: error instanceof Error ? error.message : "unknown" });
    return errorResponse("INTERNAL_ERROR", "La synchronisation a échoué", requestId, 500);
  }
}

function errorResponse(code: string, message: string, requestId: string, status: number) {
  return NextResponse.json({ error: { code, message, requestId } }, { status });
}

import { NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import { z } from "zod";
import { getDb } from "@/lib/db/client";
import { createSyncedActivityRepository } from "@/lib/db/repositories/synced-activity-repository";

const querySchema = z.object({ from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(), to: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(), limit: z.coerce.number().int().min(1).max(100).default(100) });

export async function GET(request: Request) {
  const requestId = randomUUID();
  try {
    const query = querySchema.parse(Object.fromEntries(new URL(request.url).searchParams));
    const from = `${query.from ?? "1970-01-01"}T00:00:00.000Z`;
    const to = `${query.to ?? "9999-12-31"}T23:59:59.999Z`;
    const activities = await createSyncedActivityRepository(getDb()).findByPeriod(from, to, query.limit);
    return NextResponse.json(activities.map((activity) => ({ id: activity.intervalsActivityId, name: activity.name ?? "Course à pied", type: activity.sportType, start_date: activity.startDate, distance: activity.distanceM, moving_time: activity.movingTimeS, elapsed_time: activity.elapsedTimeS, average_speed: activity.averageSpeedMps, average_heartrate: activity.averageHeartRateBpm, average_cadence: activity.averageCadenceSpm, total_elevation_gain: activity.elevationGainM, icu_training_load: activity.trainingLoad })));
  }
  catch (error) {
    if (error instanceof z.ZodError) return NextResponse.json({ error: { code: "INVALID_QUERY", message: "Les filtres de date ou la limite sont invalides", requestId } }, { status: 400 });
    console.error("[activities] local database error", { requestId, message: error instanceof Error ? error.message : "unknown" });
    return NextResponse.json({ error: { code: "DATABASE_ERROR", message: "Le cache local est indisponible", requestId } }, { status: 500 });
  }
}

"use client";

import { useEffect, useState } from "react";
import { ArrowUpRight, RefreshCw } from "lucide-react";
import Link from "next/link";
import type { Activity } from "@/lib/intervals/schemas";
import { formatDate, formatDistance, formatDuration, formatPace } from "@/lib/formatters";

type LoadState = "loading" | "ready" | "error";

export function ActivityList() {
  const [activities, setActivities] = useState<Activity[]>([]);
  const [state, setState] = useState<LoadState>("loading");
  const [error, setError] = useState<string>();
  const [syncing, setSyncing] = useState(false);
  const [syncMessage, setSyncMessage] = useState<string>();
  const [syncError, setSyncError] = useState<string>();
  async function fetchActivities(): Promise<Activity[]> {
    const response = await fetch("/api/activities");
    const payload: unknown = await response.json();
    if (!response.ok || !Array.isArray(payload)) throw new Error(response.status === 429 ? "RATE_LIMIT" : "FETCH_ERROR");
    return payload as Activity[];
  }
  async function loadActivities() {
    setState("loading");
    try {
      setActivities(await fetchActivities()); setState("ready");
    } catch (loadError) { setError(loadError instanceof Error ? loadError.message : "FETCH_ERROR"); setState("error"); }
  }
  async function synchronize() {
    setSyncing(true); setSyncMessage(undefined); setSyncError(undefined);
    try {
      const response = await fetch("/api/sync/activities", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({}) });
      const payload: unknown = await response.json();
      if (!response.ok) { const errorPayload = payload as { error?: { message?: string; requestId?: string } }; throw new Error(`${errorPayload.error?.message ?? "La synchronisation a échoué"}${errorPayload.error?.requestId ? ` (référence : ${errorPayload.error.requestId})` : ""}`); }
      const result = payload as { createdCount?: number; updatedCount?: number };
      setSyncMessage(`Synchronisation terminée : ${result.createdCount ?? 0} créées, ${result.updatedCount ?? 0} mises à jour.`);
      await loadActivities();
    } catch (syncLoadError) { setSyncError(syncLoadError instanceof Error ? syncLoadError.message : "La synchronisation a échoué"); }
    finally { setSyncing(false); }
  }
  useEffect(() => { void fetchActivities().then((loadedActivities) => { setActivities(loadedActivities); setState("ready"); }).catch((loadError: unknown) => { setError(loadError instanceof Error ? loadError.message : "FETCH_ERROR"); setState("error"); }); }, []);
  if (state === "loading") return <section className="panel state"><span className="spinner" />Chargement de vos activités...</section>;
  if (state === "error") return <section className="panel state error"><strong>Impossible de charger les activités.</strong><p>{error === "RATE_LIMIT" ? "La limite de requêtes Intervals.icu est atteinte. Réessayez dans quelques instants." : "Vérifiez votre cache local et relancez une synchronisation."}</p><button className="button" onClick={() => void synchronize()} disabled={syncing}><RefreshCw size={16} /> {syncing ? "Synchronisation..." : "Synchroniser"}</button></section>;
  if (activities.length === 0) return <section className="panel state"><strong>Aucune activité synchronisée.</strong><p>Votre cache local est vide. Lancez une synchronisation manuelle pour importer vos courses.</p><button className="button" onClick={() => void synchronize()} disabled={syncing}><RefreshCw size={16} /> {syncing ? "Synchronisation..." : "Synchroniser les activités"}</button>{syncError && <p className="sync-error">{syncError}</p>}</section>;
  return <section className="activities-section"><div className="section-heading"><div><p className="kicker">Cache local · courses uniquement</p><h2>Vos activités</h2></div><button className="button" onClick={() => void synchronize()} disabled={syncing}><RefreshCw size={16} /> {syncing ? "Synchronisation..." : "Synchroniser"}</button></div>{syncMessage && <p className="sync-message">{syncMessage}</p>}{syncError && <p className="sync-error">{syncError}</p>}<div className="activity-grid">{activities.map((activity) => <Link className="activity-card" href={`/activities/${encodeURIComponent(activity.id)}`} key={activity.id}><div className="card-top"><span>{formatDate(activity.start_date_local ?? activity.start_date)}</span><ArrowUpRight size={18} /></div><h3>{activity.name}</h3><span className="sport">{activity.type}</span><div className="metrics"><div><small>DISTANCE</small><strong>{formatDistance(activity.distance)}</strong></div><div><small>DURÉE</small><strong>{formatDuration(activity.moving_time ?? activity.elapsed_time)}</strong></div><div><small>ALLURE</small><strong>{formatPace(activity.average_speed)}</strong></div></div></Link>)}</div></section>;
}

