import { z } from "zod";

export const manualDisciplineSchema = z.enum(["strength_training", "swimming", "mobility", "other"]);
export const confirmationTypeSchema = z.enum(["performance_test_candidate", "cadence_drill_candidate", "session_intent_missing", "data_quality_review"]);
export const confirmationStatusSchema = z.enum(["detected", "confirmed", "dismissed"]);
export const detectionConfidenceSchema = z.enum(["low", "medium", "high"]);
export const contextStatusSchema = z.enum(["draft", "active", "archived"]);
export const goalPrioritySchema = z.enum(["primary", "secondary"]);
export const goalStatusSchema = z.enum(["active", "paused", "completed", "archived"]);
export const localDateSchema = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "La date doit respecter YYYY-MM-DD").refine((value) => !Number.isNaN(Date.parse(`${value}T00:00:00Z`)), "La date est invalide");
export const manualSessionInputSchema = z.object({
  sessionDate: localDateSchema,
  discipline: manualDisciplineSchema,
  durationMinutes: z.number().int().positive().max(720),
  label: z.string().trim().max(100).optional(),
  note: z.string().trim().max(500).optional(),
});

export const confirmationPayloadSchema = z.record(z.string(), z.unknown());
export const activityDetailCacheSchema = z.object({ id: z.string(), name: z.string().optional(), sportType: z.string().optional() }).strict();
export const streamSummarySchema = z.object({ version: z.string(), metrics: z.record(z.string(), z.number().finite()) }).strict();
export const athleteContextSchema = z.object({ goals: z.array(z.string()).default([]), weekTemplate: z.array(z.object({ dayOfWeek: z.number().int().min(0).max(6), label: z.string() }).strict()).default([]), notes: z.string().optional() }).strict();
export const goalDefinitionSchema = z.record(z.string(), z.unknown());

export type ManualDiscipline = z.infer<typeof manualDisciplineSchema>;
export type ConfirmationType = z.infer<typeof confirmationTypeSchema>;
export type ConfirmationStatus = z.infer<typeof confirmationStatusSchema>;
export type DetectionConfidence = z.infer<typeof detectionConfidenceSchema>;
export type ContextStatus = z.infer<typeof contextStatusSchema>;
export type GoalPriority = z.infer<typeof goalPrioritySchema>;
export type GoalStatus = z.infer<typeof goalStatusSchema>;
export type ConfirmationPayload = z.infer<typeof confirmationPayloadSchema>;
export type ActivityDetailCache = z.infer<typeof activityDetailCacheSchema>;
export type StreamSummary = z.infer<typeof streamSummarySchema>;
export type AthleteContext = z.infer<typeof athleteContextSchema>;
export type GoalDefinition = z.infer<typeof goalDefinitionSchema>;

export function serializeJson<T>(schema: z.ZodType<T>, value: T): string {
  return JSON.stringify(schema.parse(value));
}

export function parseJson<T>(schema: z.ZodType<T>, value: string): T {
  return schema.parse(JSON.parse(value) as unknown);
}

import { and, desc, eq, gte, lte } from "drizzle-orm";
import { getDb, type AppDatabase } from "../client";
import { manualSessions } from "../schema";
import { localDateSchema, manualSessionInputSchema } from "../contracts";
import type { ManualSession, NewManualSession } from "../types";

function validate(input: NewManualSession): NewManualSession {
  const parsed = manualSessionInputSchema.parse({ sessionDate: input.sessionDate, discipline: input.discipline, durationMinutes: input.durationMinutes, label: input.label ?? undefined, note: input.note ?? undefined });
  return { ...input, label: parsed.label || null, note: parsed.note || null };
}

export function createManualSessionRepository(database: AppDatabase = getDb()) {
  return {
    async create(input: NewManualSession): Promise<ManualSession> { const [row] = await database.insert(manualSessions).values(validate(input)).returning(); return row; },
    async findById(id: string): Promise<ManualSession | undefined> { return database.query.manualSessions.findFirst({ where: eq(manualSessions.id, id) }); },
    async findByPeriod(from: string, to: string): Promise<ManualSession[]> { localDateSchema.parse(from); localDateSchema.parse(to); return database.select().from(manualSessions).where(and(gte(manualSessions.sessionDate, from), lte(manualSessions.sessionDate, to))).orderBy(desc(manualSessions.sessionDate), desc(manualSessions.id)); },
    async update(id: string, changes: Partial<NewManualSession>): Promise<ManualSession | undefined> { const existing = await database.query.manualSessions.findFirst({ where: eq(manualSessions.id, id) }); if (!existing) return undefined; const merged = validate({ ...existing, ...changes, id: existing.id, createdAt: existing.createdAt, updatedAt: new Date().toISOString() }); const [row] = await database.update(manualSessions).set({ sessionDate: merged.sessionDate, discipline: merged.discipline, durationMinutes: merged.durationMinutes, label: merged.label, note: merged.note, updatedAt: merged.updatedAt }).where(eq(manualSessions.id, id)).returning(); return row; },
    async remove(id: string): Promise<void> { await database.delete(manualSessions).where(eq(manualSessions.id, id)); },
  };
}

import { randomUUID } from "node:crypto";
import { NextResponse } from "next/server";
import { z } from "zod";
import { getDb, type AppDatabase } from "@/lib/db/client";
import { manualSessionInputSchema } from "@/lib/db/contracts";
import { createManualSessionRepository } from "@/lib/db/repositories/manual-session-repository";

const querySchema = z.object({ from: z.string().optional(), to: z.string().optional() }).strict();

export async function GET(request: Request) {
  return getManualSessions(request, getDb());
}

export async function getManualSessions(request: Request, database: AppDatabase) {
  const requestId = randomUUID();
  try {
    const query = querySchema.parse(Object.fromEntries(new URL(request.url).searchParams));
    const sessions = await createManualSessionRepository(database).findByPeriod(query.from ?? "0000-01-01", query.to ?? "9999-12-31");
    return NextResponse.json(sessions);
  } catch (error) {
    if (error instanceof z.ZodError) return errorResponse("VALIDATION_ERROR", "Les dates demandées sont invalides", requestId, 400);
    console.error("[manual-sessions] read error", { requestId, message: error instanceof Error ? error.message : "unknown" });
    return errorResponse("DATABASE_ERROR", "Les activités manuelles sont indisponibles", requestId, 500);
  }
}

export async function POST(request: Request) {
  return createManualSession(request, getDb());
}

export async function createManualSession(request: Request, database: AppDatabase) {
  const requestId = randomUUID();
  try {
    const payload: unknown = await request.json();
    const input = manualSessionInputSchema.parse(payload);
    const now = new Date().toISOString();
    const session = await createManualSessionRepository(database).create({ id: randomUUID(), ...input, label: input.label || null, note: input.note || null, createdAt: now, updatedAt: now });
    return NextResponse.json(session, { status: 201 });
  } catch (error) {
    if (error instanceof z.ZodError) return errorResponse("VALIDATION_ERROR", "Vérifiez la date, le type, la durée et les textes saisis", requestId, 400);
    console.error("[manual-sessions] create error", { requestId, message: error instanceof Error ? error.message : "unknown" });
    return errorResponse("DATABASE_ERROR", "L’activité manuelle n’a pas pu être enregistrée", requestId, 500);
  }
}

function errorResponse(code: string, message: string, requestId: string, status: number) {
  return NextResponse.json({ error: { code, message, requestId } }, { status });
}

import { randomUUID } from "node:crypto";
import { NextResponse } from "next/server";
import { z } from "zod";
import { getDb, type AppDatabase } from "@/lib/db/client";
import { manualSessionInputSchema } from "@/lib/db/contracts";
import { createManualSessionRepository } from "@/lib/db/repositories/manual-session-repository";

type RouteParams = { params: Promise<{ id: string }> };

export async function PATCH(request: Request, context: RouteParams) {
  const { id } = await context.params;
  return updateManualSession(request, id, getDb());
}

export async function updateManualSession(request: Request, id: string, database: AppDatabase) {
  const requestId = randomUUID();
  try {
    const payload: unknown = await request.json();
    const input = manualSessionInputSchema.partial().strict().parse(payload);
    const session = await createManualSessionRepository(database).update(id, input);
    if (!session) return errorResponse("NOT_FOUND", "Activité manuelle introuvable", requestId, 404);
    return NextResponse.json(session);
  } catch (error) {
    if (error instanceof z.ZodError) return errorResponse("VALIDATION_ERROR", "Vérifiez les champs de l’activité manuelle", requestId, 400);
    console.error("[manual-sessions] update error", { requestId, message: error instanceof Error ? error.message : "unknown" });
    return errorResponse("DATABASE_ERROR", "L’activité manuelle n’a pas pu être modifiée", requestId, 500);
  }
}

export async function DELETE(_request: Request, context: RouteParams) {
  const { id } = await context.params;
  return deleteManualSession(id, getDb());
}

export async function deleteManualSession(id: string, database: AppDatabase) {
  const requestId = randomUUID();
  try {
    const repository = createManualSessionRepository(database);
    if (!(await repository.findById(id))) return errorResponse("NOT_FOUND", "Activité manuelle introuvable", requestId, 404);
    await repository.remove(id);
    return new NextResponse(null, { status: 204 });
  } catch (error) {
    console.error("[manual-sessions] delete error", { requestId, message: error instanceof Error ? error.message : "unknown" });
    return errorResponse("DATABASE_ERROR", "L’activité manuelle n’a pas pu être supprimée", requestId, 500);
  }
}

function errorResponse(code: string, message: string, requestId: string, status: number) {
  return NextResponse.json({ error: { code, message, requestId } }, { status });
}

"use client";

import { useState } from "react";

export type ManualSessionFormValue = { sessionDate: string; discipline: "strength_training" | "swimming" | "mobility" | "other"; durationMinutes: number; label?: string; note?: string };
type Props = { initialValue?: ManualSessionFormValue; onSubmit: (value: ManualSessionFormValue) => Promise<void>; onCancel: () => void };

function today(): string { const date = new Date(); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }

export function ManualSessionForm({ initialValue, onSubmit, onCancel }: Props) {
  const [value, setValue] = useState<ManualSessionFormValue>(initialValue ?? { sessionDate: today(), discipline: "strength_training", durationMinutes: 30 });
  const [error, setError] = useState<string>();
  const [saving, setSaving] = useState(false);
  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault(); setError(undefined);
    if (!value.sessionDate || !Number.isInteger(value.durationMinutes) || value.durationMinutes < 1 || value.durationMinutes > 720) { setError("Indiquez une date et une durée entre 1 et 720 minutes."); return; }
    if ((value.label?.length ?? 0) > 100 || (value.note?.length ?? 0) > 500) { setError("Le libellé doit faire 100 caractères maximum et la note 500."); return; }
    setSaving(true); try { await onSubmit({ ...value, label: value.label?.trim() || undefined, note: value.note?.trim() || undefined }); } catch (submitError) { setError(submitError instanceof Error ? submitError.message : "Impossible d’enregistrer l’activité."); } finally { setSaving(false); }
  }
  return <form className="manual-form" onSubmit={submit}><div className="form-grid"><label>Date<input type="date" value={value.sessionDate} onChange={(event) => setValue({ ...value, sessionDate: event.target.value })} required /></label><label>Type<select value={value.discipline} onChange={(event) => setValue({ ...value, discipline: event.target.value as ManualSessionFormValue["discipline"] })}><option value="strength_training">Musculation</option><option value="swimming">Natation</option><option value="mobility">Mobilité</option><option value="other">Autre</option></select></label><label>Durée (min)<input type="number" min="1" max="720" step="1" value={value.durationMinutes} onChange={(event) => setValue({ ...value, durationMinutes: Number(event.target.value) })} required /><span className="quick-values">{[30, 45, 60].map((minutes) => <button type="button" key={minutes} onClick={() => setValue({ ...value, durationMinutes: minutes })}>{minutes}</button>)}</span></label><label>Libellé <span className="optional">facultatif</span><input maxLength={100} value={value.label ?? ""} onChange={(event) => setValue({ ...value, label: event.target.value })} /></label><label className="wide">Note <span className="optional">facultative</span><textarea maxLength={500} rows={2} value={value.note ?? ""} onChange={(event) => setValue({ ...value, note: event.target.value })} /></label></div>{error && <p className="form-error">{error}</p>}<div className="form-actions"><button type="button" className="quiet-button" onClick={onCancel}>Annuler</button><button className="button" disabled={saving}>{saving ? "Enregistrement..." : "Enregistrer"}</button></div></form>;
}

