import type { CalendarDisplayItem, DashboardPeriod } from "@/lib/dashboard/types";
import { CalendarActivityItem } from "./calendar-activity-item";

export function WeekCalendar({ period, items }: { period: DashboardPeriod; items: CalendarDisplayItem[] }) {
  return <div className="calendar-grid week-grid">{Array.from({ length: 7 }, (_, index) => { const date = addDays(period.start, index); const dayItems = items.filter((item) => item.date === date); return <div className="calendar-day" key={date}><div className="day-heading"><small>{new Date(`${date}T00:00:00Z`).toLocaleDateString("fr-FR", { weekday: "short", timeZone: "UTC" })}</small><strong>{date.slice(8)}</strong></div><div className="day-items">{dayItems.length ? dayItems.map((item) => <CalendarActivityItem item={item} key={`${item.source}-${item.id}`} />) : <span className="day-empty">·</span>}</div></div>; })}</div>;
}
function addDays(date: string, days: number): string { const value = new Date(`${date}T00:00:00Z`); value.setUTCDate(value.getUTCDate() + days); return value.toISOString().slice(0, 10); }

import type { CalendarDisplayItem, DashboardPeriod } from "@/lib/dashboard/types";
import { CalendarActivityItem } from "./calendar-activity-item";

export function MonthCalendar({ period, items, selectedDate }: { period: DashboardPeriod; items: CalendarDisplayItem[]; selectedDate: string }) {
  const month = selectedDate.slice(0, 7);
  const days = Array.from({ length: 42 }, (_, index) => addDays(period.start, index));
  return <div className="calendar-grid month-grid">{days.map((date) => { const dayItems = items.filter((item) => item.date === date); return <div className={`calendar-day month-day ${date.slice(0, 7) === month ? "" : "outside-month"}`} key={date}><div className="day-heading"><small>{date.slice(8)}</small></div><div className="day-items">{dayItems.slice(0, 3).map((item) => <CalendarActivityItem item={item} key={`${item.source}-${item.id}`} />)}{dayItems.length > 3 && <span className="more-items">+{dayItems.length - 3} autres</span>}</div></div>; })}</div>;
}
function addDays(date: string, days: number): string { const value = new Date(`${date}T00:00:00Z`); value.setUTCDate(value.getUTCDate() + days); return value.toISOString().slice(0, 10); }

"use client";

import { useEffect, useState } from "react";
import { ChevronLeft, ChevronRight, RefreshCw } from "lucide-react";
import type { CalendarDisplayItem, DashboardPeriod, RunningDashboardSummary, WeeklyRunningVolume } from "@/lib/dashboard/types";
import { DashboardSummary } from "./dashboard-summary";
import { WeeklyRunningVolumeChart } from "./weekly-running-volume-chart";
import { CalendarViewToggle } from "./calendar-view-toggle";
import { WeekCalendar } from "./week-calendar";
import { MonthCalendar } from "./month-calendar";

type DashboardData = { period: DashboardPeriod; calendarItems: CalendarDisplayItem[]; runningSummary12Weeks: RunningDashboardSummary; weeklyRunningVolume12Weeks: WeeklyRunningVolume[] };
type View = "week" | "month";

function today(): string { return new Date().toISOString().slice(0, 10); }
function shiftMonth(date: string, amount: number): string { const value = new Date(`${date}T00:00:00Z`); value.setUTCMonth(value.getUTCMonth() + amount); return value.toISOString().slice(0, 10); }
function shiftWeek(date: string, amount: number): string { const value = new Date(`${date}T00:00:00Z`); value.setUTCDate(value.getUTCDate() + amount * 7); return value.toISOString().slice(0, 10); }

export function Dashboard() {
  const [view, setView] = useState<View>("week");
  const [date, setDate] = useState(today);
  const [data, setData] = useState<DashboardData>();
  const [error, setError] = useState<string>();
  async function fetchDashboard(): Promise<DashboardData> { const response = await fetch(`/api/dashboard?date=${date}&view=${view}`); const payload: unknown = await response.json(); if (!response.ok) { const errorPayload = payload as { error?: { message?: string; requestId?: string } }; throw new Error(`${errorPayload.error?.message ?? "Le dashboard est indisponible"}${errorPayload.error?.requestId ? ` (référence : ${errorPayload.error.requestId})` : ""}`); } return payload as DashboardData; }
  useEffect(() => { let active = true; void fetchDashboard().then((nextData) => { if (active) { setData(nextData); setError(undefined); } }).catch((loadError: unknown) => { if (active) setError(loadError instanceof Error ? loadError.message : "Le dashboard est indisponible"); }); return () => { active = false; }; }, [date, view]);
  const navigate = (amount: number) => setDate((current) => view === "week" ? shiftWeek(current, amount) : shiftMonth(current, amount));
  return <section className="dashboard"><div className="dashboard-toolbar"><div className="period-controls"><button className="icon-button" aria-label="Période précédente" title="Précédent" onClick={() => navigate(-1)}><ChevronLeft size={18} /></button><button className="today-button" onClick={() => setDate(today())}>Aujourd&apos;hui</button><button className="icon-button" aria-label="Période suivante" title="Suivant" onClick={() => navigate(1)}><ChevronRight size={18} /></button></div><CalendarViewToggle view={view} onChange={setView} /></div>{error ? <div className="panel state error"><strong>Le dashboard ne peut pas être chargé.</strong><p>{error}</p><button className="button" onClick={() => setDate((current) => current)}><RefreshCw size={16} /> Réessayer</button></div> : !data ? <div className="panel state"><span className="spinner" />Chargement du dashboard...</div> : <><DashboardSummary summary={data.runningSummary12Weeks} /><WeeklyRunningVolumeChart data={data.weeklyRunningVolume12Weeks} /><section className="calendar-panel"><div className="section-heading"><div><p className="kicker">{view === "week" ? "Semaine" : "Mois"} · Course et activités manuelles</p><h2>Calendrier</h2></div><span className="calendar-legend">Course uniquement pour le volume</span></div>{view === "week" ? <WeekCalendar period={data.period} items={data.calendarItems} /> : <MonthCalendar period={data.period} items={data.calendarItems} selectedDate={date} />}</section></>}</section>;
}

