import { z } from "zod";

export const manualDisciplineSchema = z.enum(["strength_training", "swimming", "mobility", "other"]);
export const confirmationTypeSchema = z.enum(["performance_test_candidate", "cadence_drill_candidate", "session_intent_missing", "data_quality_review"]);
export const confirmationStatusSchema = z.enum(["detected", "confirmed", "dismissed"]);
export const detectionConfidenceSchema = z.enum(["low", "medium", "high"]);
export const contextStatusSchema = z.enum(["draft", "active", "archived"]);
export const goalPrioritySchema = z.enum(["primary", "secondary"]);
export const goalStatusSchema = z.enum(["active", "paused", "completed", "archived"]);
export const localDateSchema = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "La date doit respecter YYYY-MM-DD").refine((value) => !Number.isNaN(Date.parse(`${value}T00:00:00Z`)), "La date est invalide");
export const manualSessionInputSchema = z.object({
  sessionDate: localDateSchema,
  discipline: manualDisciplineSchema,
  durationMinutes: z.number().int().positive().max(720),
  label: z.string().trim().max(100).optional(),
  note: z.string().trim().max(500).optional(),
});

export const confirmationPayloadSchema = z.record(z.string(), z.unknown());
export const activityDetailCacheSchema = z.object({ id: z.string(), name: z.string().optional(), sportType: z.string().optional() }).strict();
export const streamSummarySchema = z.object({ version: z.string(), metrics: z.record(z.string(), z.number().finite()) }).strict();
const boundedText = (max: number) => z.string().trim().max(max);
const activityKindSchema = z.enum(["running", "swimming", "strength_training", "mobility", "rest", "other"]);
const weeklyAvailabilitySchema = z.object({ activities: z.array(activityKindSchema).max(6), note: boundedText(300).optional(), flexible: z.boolean().default(false) }).strict();
export const athleteContextSchema = z.object({
  version: z.literal(1),
  athleteProfile: z.object({ experienceLevel: z.enum(["beginner", "intermediate", "confirmed", "advanced"]).optional(), notes: boundedText(500).optional() }).strict(),
  performanceReferences: z.array(z.object({ id: boundedText(80), label: boundedText(100), value: boundedText(100), source: boundedText(100).optional(), observedDate: localDateSchema.optional(), note: boundedText(300).optional() }).strict()).max(20),
  priorities: z.object({ primary: boundedText(200).optional(), secondary: z.array(boundedText(200)).max(10) }).strict(),
  weeklyTemplate: z.object({ monday: weeklyAvailabilitySchema.optional(), tuesday: weeklyAvailabilitySchema.optional(), wednesday: weeklyAvailabilitySchema.optional(), thursday: weeklyAvailabilitySchema.optional(), friday: weeklyAvailabilitySchema.optional(), saturday: weeklyAvailabilitySchema.optional(), sunday: weeklyAvailabilitySchema.optional() }).strict(),
  currentBlock: z.object({ title: boundedText(150).optional(), durationWeeks: z.number().int().min(1).max(52).optional(), priority: boundedText(200).optional(), description: boundedText(1000).optional(), personalRules: z.array(boundedText(200)).max(10).optional() }).strict().optional(),
  coachingPreferences: z.object({ wantsCriticalDataGroundedFeedback: z.boolean(), wantsTrainingScenariosToReview: z.boolean(), wantsSourcesAndLimitationsAlwaysVisible: z.boolean() }).strict(),
}).strict();
export const goalDefinitionSchema = z.record(z.string(), z.unknown());
export const goalTypeSchema = z.enum(["general", "race", "performance", "process", "technical_observation"]);
export const goalInputSchema = z.object({ title: boundedText(150).min(1), type: goalTypeSchema, priority: goalPrioritySchema, status: z.enum(["active", "paused"]).default("active"), startDate: localDateSchema.optional(), targetDate: localDateSchema.optional(), targetValue: z.number().finite().optional(), targetUnit: boundedText(50).optional(), description: boundedText(1000).optional(), definition: goalDefinitionSchema.default({}) }).strict();

export type ManualDiscipline = z.infer<typeof manualDisciplineSchema>;
export type ConfirmationType = z.infer<typeof confirmationTypeSchema>;
export type ConfirmationStatus = z.infer<typeof confirmationStatusSchema>;
export type DetectionConfidence = z.infer<typeof detectionConfidenceSchema>;
export type ContextStatus = z.infer<typeof contextStatusSchema>;
export type GoalPriority = z.infer<typeof goalPrioritySchema>;
export type GoalStatus = z.infer<typeof goalStatusSchema>;
export type ConfirmationPayload = z.infer<typeof confirmationPayloadSchema>;
export type ActivityDetailCache = z.infer<typeof activityDetailCacheSchema>;
export type StreamSummary = z.infer<typeof streamSummarySchema>;
export type AthleteContextV1 = z.infer<typeof athleteContextSchema>;
export type AthleteContext = AthleteContextV1;
export type GoalInput = z.infer<typeof goalInputSchema>;
export type GoalDefinition = z.infer<typeof goalDefinitionSchema>;

export function serializeJson<T>(schema: z.ZodType<T>, value: T): string {
  return JSON.stringify(schema.parse(value));
}

export function parseJson<T>(schema: z.ZodType<T>, value: string): T {
  return schema.parse(JSON.parse(value) as unknown);
}

import { and, eq, ne } from "drizzle-orm";
import { getDb, type AppDatabase } from "../client";
import { athleteContextSchema, contextStatusSchema, parseJson, serializeJson } from "../contracts";
import { athleteContextVersions } from "../schema";
import type { AthleteContextVersion, NewAthleteContextVersion } from "../types";

export function createAthleteContextRepository(database: AppDatabase = getDb()) {
  return {
    async create(input: NewAthleteContextVersion): Promise<AthleteContextVersion> { contextStatusSchema.parse(input.status); const context = parseJson(athleteContextSchema, input.contextJson); const [row] = await database.insert(athleteContextVersions).values({ ...input, contextJson: serializeJson(athleteContextSchema, context) }).returning(); return row; },
    async findById(id: string): Promise<AthleteContextVersion | undefined> { return database.query.athleteContextVersions.findFirst({ where: eq(athleteContextVersions.id, id) }); },
    async findActive(): Promise<AthleteContextVersion | undefined> { return database.query.athleteContextVersions.findFirst({ where: eq(athleteContextVersions.status, "active") }); },
    async createAndActivate(input: NewAthleteContextVersion): Promise<AthleteContextVersion> { contextStatusSchema.parse(input.status); const context = parseJson(athleteContextSchema, input.contextJson); return database.transaction((transaction) => { const now = new Date().toISOString(); transaction.update(athleteContextVersions).set({ status: "archived", archivedAt: now, updatedAt: now }).where(eq(athleteContextVersions.status, "active")).run(); const [row] = transaction.insert(athleteContextVersions).values({ ...input, status: "active", contextJson: serializeJson(athleteContextSchema, context), activatedAt: now, createdAt: now, updatedAt: now }).returning().all(); return row; }); },
    async activate(id: string): Promise<AthleteContextVersion | undefined> { const now = new Date().toISOString(); return database.transaction((transaction) => { transaction.update(athleteContextVersions).set({ status: "archived", archivedAt: now, updatedAt: now }).where(and(eq(athleteContextVersions.status, "active"), ne(athleteContextVersions.id, id))).run(); const [row] = transaction.update(athleteContextVersions).set({ status: "active", activatedAt: now, updatedAt: now }).where(eq(athleteContextVersions.id, id)).returning().all(); return row; }); },
  };
}

import { and, eq, ne } from "drizzle-orm";
import { getDb, type AppDatabase } from "../client";
import { goalDefinitionSchema, goalPrioritySchema, goalStatusSchema, parseJson, serializeJson } from "../contracts";
import { goals } from "../schema";
import type { Goal, NewGoal } from "../types";

export function createGoalRepository(database: AppDatabase = getDb()) {
  return {
    async create(input: NewGoal): Promise<Goal> { goalPrioritySchema.parse(input.priority); goalStatusSchema.parse(input.status); const definition = parseJson(goalDefinitionSchema, input.definitionJson); const values = { ...input, definitionJson: serializeJson(goalDefinitionSchema, definition) }; return database.transaction((transaction) => { if (input.priority === "primary" && input.status === "active" && transaction.select().from(goals).where(and(eq(goals.priority, "primary"), eq(goals.status, "active"))).all().length > 0) throw new Error("Un seul objectif principal actif est autorisé"); const [row] = transaction.insert(goals).values(values).returning().all(); return row; }); },
    async findById(id: string): Promise<Goal | undefined> { return database.query.goals.findFirst({ where: eq(goals.id, id) }); },
    async findAll(includeArchived = false): Promise<Goal[]> { const rows = await database.select().from(goals).orderBy(goals.status, goals.priority, goals.targetDate); return includeArchived ? rows : rows.filter((goal) => goal.status !== "archived"); },
    async update(id: string, changes: Partial<NewGoal>): Promise<Goal | undefined> { if (changes.priority) goalPrioritySchema.parse(changes.priority); if (changes.status) goalStatusSchema.parse(changes.status); if (changes.definitionJson) { const definition = parseJson(goalDefinitionSchema, changes.definitionJson); changes.definitionJson = serializeJson(goalDefinitionSchema, definition); } return database.transaction((transaction) => { if (changes.priority === "primary" && changes.status === "active" && transaction.select().from(goals).where(and(eq(goals.priority, "primary"), eq(goals.status, "active"), ne(goals.id, id))).all().length > 0) throw new Error("Un seul objectif principal actif est autorisé"); const [row] = transaction.update(goals).set(changes).where(eq(goals.id, id)).returning().all(); return row; }); },
    async archive(id: string): Promise<Goal | undefined> { const [row] = await database.update(goals).set({ status: "archived", updatedAt: new Date().toISOString() }).where(eq(goals.id, id)).returning(); return row; },
  };
}

import { randomUUID } from "node:crypto";
import { NextResponse } from "next/server";
import { z } from "zod";
import { getDb } from "@/lib/db/client";
import { athleteContextSchema, serializeJson } from "@/lib/db/contracts";
import { createAthleteContextRepository } from "@/lib/db/repositories/athlete-context-repository";

const inputSchema = z.object({ context: athleteContextSchema, sourceText: z.string().trim().max(2000).optional() }).strict();

export async function GET() {
  const requestId = randomUUID();
  try { const row = await createAthleteContextRepository(getDb()).findActive(); return NextResponse.json(row ? { id: row.id, createdAt: row.createdAt, activatedAt: row.activatedAt, context: JSON.parse(row.contextJson) as unknown } : null); }
  catch (error) { console.error("[context] read error", { requestId, message: error instanceof Error ? error.message : "unknown" }); return errorResponse("DATABASE_ERROR", "Le contexte est indisponible", requestId, 500); }
}

export async function PUT(request: Request) {
  const requestId = randomUUID();
  try { const payload: unknown = await request.json(); const input = inputSchema.parse(payload); const now = new Date().toISOString(); const row = await createAthleteContextRepository(getDb()).createAndActivate({ id: randomUUID(), status: "active", contextJson: serializeJson(athleteContextSchema, input.context), sourceText: input.sourceText || null, createdAt: now, activatedAt: now, archivedAt: null, updatedAt: now }); return NextResponse.json({ id: row.id, createdAt: row.createdAt, activatedAt: row.activatedAt, context: input.context }); }
  catch (error) { if (error instanceof z.ZodError) return errorResponse("VALIDATION_ERROR", "Vérifiez les informations du contexte", requestId, 400); console.error("[context] write error", { requestId, message: error instanceof Error ? error.message : "unknown" }); return errorResponse("DATABASE_ERROR", "Le contexte n’a pas pu être enregistré", requestId, 500); }
}

function errorResponse(code: string, message: string, requestId: string, status: number) { return NextResponse.json({ error: { code, message, requestId } }, { status }); }

import { randomUUID } from "node:crypto";
import { NextResponse } from "next/server";
import { z } from "zod";
import { getDb } from "@/lib/db/client";
import { goalInputSchema, goalStatusSchema } from "@/lib/db/contracts";
import { createGoalRepository } from "@/lib/db/repositories/goal-repository";

const querySchema = z.object({ status: goalStatusSchema.optional(), includeArchived: z.coerce.boolean().default(false) }).strict();
export async function GET(request: Request) { const requestId = randomUUID(); try { const query = querySchema.parse(Object.fromEntries(new URL(request.url).searchParams)); const goals = await createGoalRepository(getDb()).findAll(query.includeArchived); const filtered = query.status ? goals.filter((goal) => goal.status === query.status) : goals; return NextResponse.json(filtered.sort((a, b) => Number(b.status === "active") - Number(a.status === "active") || Number(a.priority !== "primary") - Number(b.priority !== "primary") || (a.targetDate ?? "9999").localeCompare(b.targetDate ?? "9999") || b.updatedAt.localeCompare(a.updatedAt))); } catch (error) { if (error instanceof z.ZodError) return errorResponse("VALIDATION_ERROR", "Les filtres d’objectifs sont invalides", requestId, 400); return errorResponse("DATABASE_ERROR", "Les objectifs sont indisponibles", requestId, 500); } }
export async function POST(request: Request) { const requestId = randomUUID(); try { const input = goalInputSchema.parse(await request.json()); const now = new Date().toISOString(); const goal = await createGoalRepository(getDb()).create({ id: randomUUID(), title: input.title, type: input.type, priority: input.priority, status: input.status, startDate: input.startDate ?? null, targetDate: input.targetDate ?? null, targetValue: input.targetValue ?? null, targetUnit: input.targetUnit ?? null, description: input.description ?? null, definitionJson: JSON.stringify(input.definition), createdAt: now, updatedAt: now }); return NextResponse.json(goal, { status: 201 }); } catch (error) { if (error instanceof z.ZodError) return errorResponse("VALIDATION_ERROR", "Vérifiez les champs de l’objectif", requestId, 400); if (error instanceof Error && error.message.includes("Un seul objectif")) return errorResponse("VALIDATION_ERROR", error.message, requestId, 409); return errorResponse("DATABASE_ERROR", "L’objectif n’a pas pu être enregistré", requestId, 500); } }
function errorResponse(code: string, message: string, requestId: string, status: number) { return NextResponse.json({ error: { code, message, requestId } }, { status }); }

