ce.id ? { ...item, source: event.target.value } : item) })} /><input type="date" value={reference.observedDate ?? ""} onChange={(event) => update({ ...context, performanceReferences: context.performanceReferences.map((item) => item.id === reference.id ? { ...item, observedDate: event.target.value || undefined } : item) })} /><button type="button" className="quiet-button" onClick={() => removeReference(reference.id)}>Retirer</button></div>)}</div><div className="context-section"><p className="kicker">Priorités</p><div className="form-grid"><label>Priorité principale<input maxLength={200} value={context.priorities.primary ?? ""} onChange={(event) => update({ ...context, priorities: { ...context.priorities, primary: event.target.value || undefined } })} /></label><label>Priorités secondaires<input maxLength={200} placeholder="Séparer par des virgules" value={context.priorities.secondary.join(", ")} onChange={(event) => update({ ...context, priorities: { ...context.priorities, secondary: event.target.value.split(",").map((value) => value.trim()).filter(Boolean) } })} /></label></div></div><div className="context-section"><p className="kicker">Semaine type</p><p className="context-hint">Déclarative : elle ne crée aucun événement dans le calendrier.</p>{days.map((day, index) => { const availability = context.weeklyTemplate[day] ?? { activities: [], flexible: false }; return <div className="week-template-row" key={day}><strong>{dayLabels[index]}</strong><div className="activity-choice">{activityOptions.map(([key, label]) => <label key={key}><input type="checkbox" checked={availability.activities.includes(key)} onChange={(event) => { const activities = event.target.checked ? [...availability.activities, key] : availability.activities.filter((activity) => activity !== key); update({ ...context, weeklyTemplate: { ...context.weeklyTemplate, [day]: { ...availability, activities } } }); }} />{label}</label>)}</div><label className="flexible"><input type="checkbox" checked={availability.flexible ?? false} onChange={(event) => update({ ...context, weeklyTemplate: { ...context.weeklyTemplate, [day]: { ...availability, flexible: event.target.checked } } })} /> Flexible</label></div>; })}</div><div className="context-section"><p className="kicker">Bloc actuel</p><div className="form-grid"><label>Titre<input maxLength={150} value={context.currentBlock?.title ?? ""} onChange={(event) => update({ ...context, currentBlock: { ...context.currentBlock, title: event.target.value } })} /></label><label>Durée (semaines)<input type="number" min="1" max="52" value={context.currentBlock?.durationWeeks ?? ""} onChange={(event) => update({ ...context, currentBlock: { ...context.currentBlock, durationWeeks: event.target.value ? Number(event.target.value) : undefined } })} /></label><label className="wide">Description<textarea rows={2} maxLength={1000} value={context.currentBlock?.description ?? ""} onChange={(event) => update({ ...context, currentBlock: { ...context.currentBlock, description: event.target.value } })} /></label></div></div><div className="context-section"><p className="kicker">Préférences de lecture</p>{[["wantsCriticalDataGroundedFeedback", "Retour critique fondé sur les données"], ["wantsTrainingScenariosToReview", "Scénarios d’entraînement à examiner"], ["wantsSourcesAndLimitationsAlwaysVisible", "Sources et limites systématiquement visibles"]].map(([key, label]) => <label className="preference-row" key={key}><input type="checkbox" checked={context.coachingPreferences[key as keyof typeof context.coachingPreferences]} onChange={(event) => update({ ...context, coachingPreferences: { ...context.coachingPreferences, [key]: event.target.checked } })} />{label}</label>)}</div>{error && <p className="form-error">{error}</p>}<div className="form-actions"><span className="context-version">{activeDate ? `Version active depuis le ${new Date(activeDate).toLocaleDateString("fr-FR")}.` : "Aucun contexte actif."} Chaque enregistrement crée une nouvelle ver