import type { AthleteContextV1 } from "@/lib/db/contracts";
import type { Goal } from "@/lib/db/types";
import { AthleteContextForm, emptyContext } from "./athlete-context-form";
import { GoalForm } from "./goal-form";
import { GoalItem } from "./goal-item";

export function ContextPage() {
  const [context, setContext] = useState<AthleteContextV1>(emptyContext); const [activatedAt, setActivatedAt] = useState<string | null>(null); const [goals, setGoals] = useState<Goal[]>([]); const [loading, setLoading] = useState(true); const [goalForm, setGoalForm] = useState(false); const [error, setError] = useState<string>();
  useEffect(() => { void Promise.all([fetch("/api/context").then((response) => response.json() as Promise<{ context?: AthleteContextV1; activatedAt?: string | null } | null>), fetch("/api/goals").then((response) => response.json() as Promise<Goal[]>)]).then(([activeContext, loadedGoals]) => { if (activeContext?.context) { setContext(activeContext.context); setActivatedAt(activeContext.activatedAt ?? null); } setGoals(loadedGoals); }).catch(() => setError("Impossible de charger votre contexte.")).finally(() => setLoading(false)); }, []);
  if (loading) return <main className="shell"><section className="panel state"><span className="spinner" />Chargement de Mon contexte...</section></main>;
  return <main className="shell"><header className="topbar"><Link className="brand" href="/">RUN <span>INSIGHTS</span></Link><Link className="back-link" href="/">Retour au dashboard</Link></header><section className="context-hero"><p className="kicker">Cadre explicite</p><h1>Mon contexte</h1><p>Ces informations servent de cadre explicite à vos futures analyses. Elles ne sont pas déduites automatiquement de vos activités.</p></section>{error && <section className="panel state error"><p>{error}</p></section>}<AthleteContextForm initialContext={context} activeDate={activatedAt} onSaved={(saved, date) => { setContext(saved); setActivatedAt(date); }} /><section className="goals-section"><div className="section-heading"><div><p className="kicker">Objectifs structurés</p><h2>Objectifs</h2></div><button className="button" onClick={() => setGoalForm(true)}>Ajouter un objectif</button></div>{goalForm && <GoalForm onSaved={(goal) => { setGoals((current) => [goal as Goal, ...current]); setGoalForm(false); }} onCancel={() => setGoalForm(false)} />}{goals.length === 0 ? <p className="manual-empty">Aucun objectif déclaré.</p> : <div className="goal-list">{goals.map((goal) => <GoalItem key={goal.id} goal={goal} onChange={(changed) => setGoals((current) => changed.status === "archived" ? current.map((item) => item.id === changed.id ? changed : item) : current.map((item) => item.id === changed.id ? changed : item))} />)}</div>}</section></main>;
}

import { ContextPage } from "@/components/context/context-page";

export default function ContextRoute() {
  return <ContextPage />;
}

import { ActivityList } from "@/components/activity-list";
import Link from "next/link";
import { ManualSessionList } from "@/components/manual-session-list";
import { Dashboard } from "@/components/dashboard/dashboard";

export default function HomePage() {
  return <main className="shell">
    <header className="topbar"><Link className="brand" href="/">RUN <span>INSIGHTS</span></Link><nav className="main-nav"><Link href="/context">Mon contexte</Link></nav><span className="eyebrow">TABLEAU DE BORD / ACTIVITÉS</span></header>
    <section className="hero"><p className="kicker">Votre journal de course</p><h1>Les kilomètres<br /><em>tels qu&apos;ils sont.</em></h1><p className="intro">Une vue claire de vos dernières séances, synchronisées depuis Intervals.icu.</p></section>
    <Dashboard />
    <ActivityList />
    <ManualSessionList />
  </main>;
}

