import { randomUUID } from "node:crypto";
import { NextResponse } from "next/server";
import { z } from "zod";
import { getDb } from "@/lib/db/client";
import { athleteContextSchema, parseJson, serializeJson } from "@/lib/db/contracts";
import { createAthleteContextRepository } from "@/lib/db/repositories/athlete-context-repository";

const inputSchema = z.object({ context: athleteContextSchema, sourceText: z.string().trim().max(2000).optional() }).strict();

export async function GET() {
  const requestId = randomUUID();
  try { const row = await createAthleteContextRepository(getDb()).findActive(); return NextResponse.json(row ? { id: row.id, createdAt: row.createdAt, activatedAt: row.activatedAt, context: parseJson(athleteContextSchema, row.contextJson) } : null); }
  catch (error) { console.error("[context] read error", { requestId, message: error instanceof Error ? error.message : "unknown" }); return errorResponse("DATABASE_ERROR", "Le contexte est indisponible", requestId, 500); }
}

export async function PUT(request: Request) {
  const requestId = randomUUID();
  try { const payload: unknown = await request.json(); const input = inputSchema.parse(payload); const now = new Date().toISOString(); const row = await createAthleteContextRepository(getDb()).createAndActivate({ id: randomUUID(), status: "active", contextJson: serializeJson(athleteContextSchema, input.context), sourceText: input.sourceText || null, createdAt: now, activatedAt: now, archivedAt: null, updatedAt: now }); return NextResponse.json({ id: row.id, createdAt: row.createdAt, activatedAt: row.activatedAt, context: input.context }); }
  catch (error) { if (error instanceof z.ZodError) return errorResponse("VALIDATION_ERROR", "Vérifiez les informations du contexte", requestId, 400); console.error("[context] write error", { requestId, message: error instanceof Error ? error.message : "unknown" }); return errorResponse("DATABASE_ERROR", "Le contexte n’a pas pu être enregistré", requestId, 500); }
}

function errorResponse(code: string, message: string, requestId: string, status: number) { return NextResponse.json({ error: { code, message, requestId } }, { status }); }

"use client";

import { useState } from "react";
import type { GoalInput } from "@/lib/db/contracts";

type Props = { initial?: Partial<GoalInput>; goalId?: string; onSaved: (goal: unknown) => void; onCancel: () => void };
export function GoalForm({ initial, goalId, onSaved, onCancel }: Props) {
  const [value, setValue] = useState<GoalInput>({ title: initial?.title ?? "", type: initial?.type ?? "general", priority: initial?.priority ?? "secondary", status: initial?.status ?? "active", startDate: initial?.startDate, targetDate: initial?.targetDate, targetValue: initial?.targetValue, targetUnit: initial?.targetUnit, description: initial?.description, definition: initial?.definition ?? {} }); const [error, setError] = useState<string>(); const [saving, setSaving] = useState(false);
  async function submit(event: React.FormEvent) { event.preventDefault(); setSaving(true); setError(undefined); try { const response = await fetch(goalId ? `/api/goals/${goalId}` : "/api/goals", { method: goalId ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(value) }); const payload: unknown = await response.json(); if (!response.ok) throw new Error((payload as { error?: { message?: string } }).error?.message ?? "L’objectif n’a pas pu être enregistré."); onSaved(payload); } catch (submitError) { setError(submitError instanceof Error ? submitError.message : "Erreur d’enregistrement."); } finally { setSaving(false); } }
  return <form className="goal-form" onSubmit={submit}><div className="form-grid"><label>Titre<input required maxLength={150} value={value.title} onChange={(event) => setValue({ ...value, title: event.target.value })} /></label><label>Type<select value={value.type} onChange={(event) => setValue({ ...value, type: event.target.value as GoalInput["type"] })}><option value="general">Général</option><option value="race">Course</option><option value="performance">Performance</option><option value="process">Processus</option><option value="technical_observation">Observation technique</option></select></label><label>Priorité<select value={value.priority} onChange={(event) => setValue({ ...value, priority: event.target.value as GoalInput["priority"] })}><option value="secondary">Secondaire</option><option value="primary">Primary</option></select></label><label>Statut<select value={value.status} onChange={(event) => setValue({ ...value, status: event.target.value as GoalInput["status"] })}><option value="active">Actif</option><option value="paused">En pause</option></select></label><label>Échéance<input type="date" value={value.targetDate ?? ""} onChange={(event) => setValue({ ...value, targetDate: event.target.value || undefined })} /></label><label>Valeur cible<input type="number" value={value.targetValue ?? ""} onChange={(event) => setValue({ ...value, targetValue: event.target.value ? Number(event.target.value) : undefined })} /></label><label>Unité<input maxLength={50} placeholder="km, min/km..." value={value.targetUnit ?? ""} onChange={(event) => setValue({ ...value, targetUnit: event.target.value })} /></label><label className="wide">Description<textarea maxLength={1000} rows={2} value={value.description ?? ""} onChange={(event) => setValue({ ...value, description: event.target.value })} /></label></div>{value.priority === "primary" && value.status === "active" && <p className="goal-warning">Cet objectif remplacera la priorité principale active existante.</p>}{error && <p className="form-error">{error}</p>}<div className="form-actions"><button type="button" className="quiet-button" onClick={onCancel}>Annuler</button><button className="button" disabled={saving}>{saving ? "Enregistrement..." : goalId ? "Enregistrer" : "Créer l’objectif"}</button></div></form>;
}

"use client";

import { Archive, Pause, Play } from "lucide-react";
import type { Goal } from "@/lib/db/types";

export function GoalItem({ goal, onChange, onEdit }: { goal: Goal; onChange: (goal: Goal) => void; onEdit: () => void }) {
  async function update(changes: Record<string, unknown>) { const response = await fetch(`/api/goals/${goal.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(changes) }); if (response.ok) onChange(await response.json() as Goal); }
  async function archive() { const response = await fetch(`/api/goals/${goal.id}/archive`, { method: "POST" }); if (response.ok) onChange(await response.json() as Goal); }
  return <article className="goal-item"><div><span className={`goal-badge ${goal.priority}`}>{goal.priority === "primary" ? "Primary" : "Secondaire"}</span><span className="goal-status">{goal.status === "active" ? "Actif" : goal.status === "paused" ? "En pause" : "Archivé"}</span><h3>{goal.title}</h3><p>{goal.type}{goal.targetDate ? ` · échéance ${goal.targetDate}` : ""}{goal.targetValue !== null && goal.targetValue !== undefined ? ` · ${goal.targetValue} ${goal.targetUnit ?? ""}` : ""}</p></div><div className="goal-actions">{goal.status !== "archived" && <><button className="icon-button" title="Modifier" aria-label="Modifier" onClick={onEdit}><Pencil size={15} /></button><button className="icon-button" title={goal.status === "active" ? "Mettre en pause" : "Reprendre"} aria-label={goal.status === "active" ? "Mettre en pause" : "Reprendre"} onClick={() => void update({ status: goal.status === "active" ? "paused" : "active" })}>{goal.status === "active" ? <Pause size={15} /> : <Play size={15} />}</button><button className="icon-button" title="Archiver" aria-label="Archiver" onClick={() => void archive()}><Archive size={15} /></button></>}</div></article>;
}

