import { and, eq, ne } from "drizzle-orm";
import { getDb, type AppDatabase } from "../client";
import { goalDefinitionSchema, goalPrioritySchema, goalStatusSchema, parseJson, serializeJson } from "../contracts";
import { goals } from "../schema";
import type { Goal, NewGoal } from "../types";

export function createGoalRepository(database: AppDatabase = getDb()) {
  return {
    async create(input: NewGoal): Promise<Goal> { goalPrioritySchema.parse(input.priority); goalStatusSchema.parse(input.status); const definition = parseJson(goalDefinitionSchema, input.definitionJson); const values = { ...input, definitionJson: serializeJson(goalDefinitionSchema, definition) }; return database.transaction((transaction) => { if (input.priority === "primary" && input.status === "active" && transaction.select().from(goals).where(and(eq(goals.priority, "primary"), eq(goals.status, "active"))).all().length > 0) throw new Error("Un seul objectif principal actif est autorisé"); const [row] = transaction.insert(goals).values(values).returning().all(); return row; }); },
    async findById(id: string): Promise<Goal | undefined> { return database.query.goals.findFirst({ where: eq(goals.id, id) }); },
    async findAll(includeArchived = false): Promise<Goal[]> { const rows = await database.select().from(goals).orderBy(goals.status, goals.priority, goals.targetDate); return includeArchived ? rows : rows.filter((goal) => goal.status !== "archived"); },
    async update(id: string, changes: Partial<NewGoal>): Promise<Goal | undefined> { if (changes.priority) goalPrioritySchema.parse(changes.priority); if (changes.status) goalStatusSchema.parse(changes.status); if (changes.definitionJson) { const definition = parseJson(goalDefinitionSchema, changes.definitionJson); changes.definitionJson = serializeJson(goalDefinitionSchema, definition); } return database.transaction((transaction) => { const current = transaction.select().from(goals).where(eq(goals.id, id)).get(); if (!current) return undefined; const nextPriority = changes.priority ?? current.priority; const nextStatus = changes.status ?? current.status; if (nextPriority === "primary" && nextStatus === "active") { transaction.update(goals).set({ priority: "secondary", status: "paused", updatedAt: new Date().toISOString() }).where(and(eq(goals.priority, "primary"), eq(goals.status, "active"), ne(goals.id, id))).run(); } const [row] = transaction.update(goals).set(changes).where(eq(goals.id, id)).returning().all(); return row; }); },
    async archive(id: string): Promise<Goal | undefined> { const [row] = await database.update(goals).set({ status: "archived", updatedAt: new Date().toISOString() }).where(eq(goals.id, id)).returning(); return row; },
  };
}

import { randomUUID } from "node:crypto";
import { NextResponse } from "next/server";
import { z } from "zod";
import { getDb, type AppDatabase } from "@/lib/db/client";
import { athleteContextSchema, parseJson, serializeJson } from "@/lib/db/contracts";
import { createAthleteContextRepository } from "@/lib/db/repositories/athlete-context-repository";

const inputSchema = z.object({ context: athleteContextSchema, sourceText: z.string().trim().max(2000).optional() }).strict();

export async function GET() {
  return getContext(getDb());
}

export async function getContext(database: AppDatabase) {
  const requestId = randomUUID();
  try { const row = await createAthleteContextRepository(database).findActive(); return NextResponse.json(row ? { id: row.id, createdAt: row.createdAt, activatedAt: row.activatedAt, context: parseJson(athleteContextSchema, row.contextJson) } : null); }
  catch (error) { console.error("[context] read error", { requestId, message: error instanceof Error ? error.message : "unknown" }); return errorResponse("DATABASE_ERROR", "Le contexte est indisponible", requestId, 500); }
}

export async function PUT(request: Request) {
  return putContext(request, getDb());
}

export async function putContext(request: Request, database: AppDatabase) {
  const requestId = randomUUID();
  try { const payload: unknown = await request.json(); const input = inputSchema.parse(payload); const now = new Date().toISOString(); const row = await createAthleteContextRepository(database).createAndActivate({ id: randomUUID(), status: "active", contextJson: serializeJson(athleteContextSchema, input.context), sourceText: input.sourceText || null, createdAt: now, activatedAt: now, archivedAt: null, updatedAt: now }); return NextResponse.json({ id: row.id, createdAt: row.createdAt, activatedAt: row.activatedAt, context: input.context }); }
  catch (error) { if (error instanceof z.ZodError) return errorResponse("VALIDATION_ERROR", "Vérifiez les informations du contexte", requestId, 400); console.error("[context] write error", { requestId, message: error instanceof Error ? error.message : "unknown" }); return errorResponse("DATABASE_ERROR", "Le contexte n’a pas pu être enregistré", requestId, 500); }
}

function errorResponse(code: string, message: string, requestId: string, status: number) { return NextResponse.json({ error: { code, message, requestId } }, { status }); }

import { randomUUID } from "node:crypto";
import { NextResponse } from "next/server";
import { z } from "zod";
import { getDb, type AppDatabase } from "@/lib/db/client";
import { goalInputSchema, goalStatusSchema } from "@/lib/db/contracts";
import { createGoalRepository } from "@/lib/db/repositories/goal-repository";

const querySchema = z.object({ status: goalStatusSchema.optional(), includeArchived: z.coerce.boolean().default(false) }).strict();
export async function GET(request: Request) { return getGoals(request, getDb()); }
export async function getGoals(request: Request, database: AppDatabase) { const requestId = randomUUID(); try { const query = querySchema.parse(Object.fromEntries(new URL(request.url).searchParams)); const goals = await createGoalRepository(database).findAll(query.includeArchived); const filtered = query.status ? goals.filter((goal) => goal.status === query.status) : goals; return NextResponse.json(filtered.sort((a, b) => Number(b.status === "active") - Number(a.status === "active") || Number(a.priority !== "primary") - Number(b.priority !== "primary") || (a.targetDate ?? "9999").localeCompare(b.targetDate ?? "9999") || b.updatedAt.localeCompare(a.updatedAt))); } catch (error) { if (error instanceof z.ZodError) return errorResponse("VALIDATION_ERROR", "Les filtres d’objectifs sont invalides", requestId, 400); return errorResponse("DATABASE_ERROR", "Les objectifs sont indisponibles", requestId, 500); } }
export async function POST(request: Request) { return createGoal(request, getDb()); }
export async function createGoal(request: Request, database: AppDatabase) { const requestId = randomUUID(); try { const input = goalInputSchema.parse(await request.json()); const now = new Date().toISOString(); const goal = await createGoalRepository(database).create({ id: randomUUID(), title: input.title, type: input.type, priority: input.priority, status: input.status, startDate: input.startDate ?? null, targetDate: input.targetDate ?? null, targetValue: input.targetValue ?? null, targetUnit: input.targetUnit ?? null, description: input.description ?? null, definitionJson: JSON.stringify(input.definition), createdAt: now, updatedAt: now }); return NextResponse.json(goal, { status: 201 }); } catch (error) { if (error instanceof z.ZodError) return errorResponse("VALIDATION_ERROR", "Vérifiez les champs de l’objectif", requestId, 400); if (error instanceof Error && error.message.includes("Un seul objectif")) return errorResponse("VALIDATION_ERROR", error.message, requestId, 409); return errorResponse("DATABASE_ERROR", "L’objectif n’a pas pu être enregistré", requestId, 500); } }
function errorResponse(code: string, message: string, requestId: string, status: number) { return NextResponse.json({ error: { code, message, requestId } }, { status }); }

