h><th>FC moy.</th><th>Cadence</th></tr></thead><tbody>{segmented.segments.map((segment) => <tr key={`${segment.lapId}-${segment.index}`}><th>{segment.lapId} · {segment.index + 1}</th><td>{formatDuration(segment.durationS)}</td><td>{formatDistance(segment.distanceM)}</td><td>{formatPace(segment.averageSpeedMps)}</td><td>{segment.averageHeartRateBpm ? `${Math.round(segment.averageHeartRateBpm)} bpm` : "—"}</td><td>{segment.averageCadenceSpm ? `${Math.round(segment.averageCadenceSpm)} pas/min` : "—"}</td></tr>)}</tbody></table></div>}</section>}{tab === "charts" && <StreamsPanel streams={streams} error={streamError} />}</main>;
